insert into public.feature_registry(key,name,description,module_group,icon,route,sort_order,is_enabled) values ('feed','Feed','Campus social feed','social','📰','/home',10,true),('marketplace','Marketplace','Campus marketplace','commerce','🛍','/market/shop',20,true),('projects','Projects','Campus projects','collaboration','🚀','/projects',30,true),('crowdfunding','Crowdfunding','Project campaigns','finance','💰','/projects/crowdfund',31,true),('jobs','Jobs','Career opportunities','career','💼','/connect/jobs',40,true),('events','Events','Campus events','campus','🎉','/connect/events',50,true),('hostel','Hostel','Hostel services','campus','🏛','/hostel',60,true),('food_delivery','Food Delivery','Campus food','commerce','🍽','/market/food',70,true),('chat','Chat','Campus messaging','social','💬',null,80,true),('notifications','Notifications','Notifications','platform','🔔',null,90,true),('profile','Profile','Your profile','account','👤','/profile',100,true),('dashboard','Dashboard','Your dashboard','platform','⌂','/home',5,true),('admin','Admin','Administration','platform','🛡','/admin',110,true),('analytics','Analytics','Platform analytics','platform','📊',null,120,true),('settings','Settings','Account settings','account','⚙','/profile/settings',130,true),('directory','Directory','Campus directory','social','👥','/connect/alumni',35,true) on conflict(key) do update set name=excluded.name,description=excluded.description,module_group=excluded.module_group,icon=excluded.icon,route=excluded.route,sort_order=excluded.sort_order,is_enabled=excluded.is_enabled;
